Aquí va profe:

```c
#include <stdio.h>
int main() {
    int N, M, vuelo, pasajero;
    float peso, pesoTotal, promedio;
    scanf("%d %d", &N, &M);
    vuelo = 1;
    pasajero = 1;  /* lo inicialicé aquí afuera */
    while (vuelo <= N) {
        pesoTotal = 0;
        while (pasajero <= M) {
            scanf("%f", &peso);
            pesoTotal += peso;
            pasajero++;
        }
        promedio = pesoTotal / M;
        printf("Vuelo %d: total %.2f kg, promedio %.2f kg\n", vuelo, pesoTotal, promedio);
        vuelo++;
    }
    return 0;
}
```

